import { memo, useEffect } from "react";
import { useGLTF } from "@react-three/drei";
// #if DEBUG
import { useControls } from "leva";
// #endif
import { useScene } from "@/lib/contexts/SceneContext";
import { enableShadows } from "@/utils/three";

type ShelfControls = {
    shelfY: number;
    shelfZ: number;
    shelfScale: number;
};

// Generated by .bin/generate-scene-models.mts with its bottom center at the
// origin, its back on the wall and its top 1 unit high, so `shelf.scale` is
// its height
const SHELF_MODEL_PATH = "/models/cartoon_shelf.glb";

const Shelf = memo(() => {
    const { shelf } = useScene();
    const shelfModel = useGLTF(SHELF_MODEL_PATH);

    useEffect(() => {
        enableShadows(shelfModel.scene);
    }, [shelfModel.scene]);

    let shelfY: number, shelfZ: number, shelfScale: number;

    // #if DEBUG
    ({ shelfY, shelfZ, shelfScale } = useControls(
        "Shelf",
        {
            shelfY: {
                value: shelf?.position?.y ?? 0,
                min: 0,
                max: 10,
                step: 0.01,
            },
            shelfZ: {
                value: shelf?.position?.z ?? 0,
                min: -14,
                max: 14,
                step: 0.01,
            },
            shelfScale: {
                value: shelf?.scale ?? 1,
                min: 1,
                max: 8,
                step: 0.01,
            },
        },
        { collapsed: true }
    ) as ShelfControls);
    // #endif

    // #if !DEBUG
    shelfY = shelf?.position?.y ?? 0;
    shelfZ = shelf?.position?.z ?? 0;
    shelfScale = shelf?.scale ?? 1;
    // #endif

    return (
        <primitive
            object={shelfModel.scene}
            position={[shelf?.position?.x ?? 0, shelfY, shelfZ]}
            rotation={[0, shelf?.rotation?.y ?? 0, 0]}
            scale={[shelfScale, shelfScale, shelfScale]}
        />
    );
});
Shelf.displayName = "Shelf";

useGLTF.preload(SHELF_MODEL_PATH);

export default Shelf;
